const nativeMarkupCache=new Map(),nativePageCache=new Map();
async function inlineNativeFigures(root,questionPath){
  const uses=[...root.querySelectorAll('use.native-figures')];
  for(const use of uses){
    const raw=use.getAttribute('href')||use.getAttribute('xlink:href')||'';
    const [asset]=raw.split('#'); if(!asset)continue;
    let pending=nativePageCache.get(asset);
    if(!pending){pending=fetch(new URL(asset, new URL(questionPath, location.href)).href).then(r=>{if(!r.ok)throw Error('Gráficos indisponíveis');return r.text()});nativePageCache.set(asset,pending)}
    const source=await pending;
    const doc=new DOMParser().parseFromString(source,'image/svg+xml');
    const prefix='n'+Math.random().toString(36).slice(2,9);
    const replacement=document.createElementNS('http://www.w3.org/2000/svg','g'); replacement.setAttribute('class','native-figures'); replacement.setAttribute('aria-hidden','true');
    const rewrite=node=>{for(const attr of [...node.attributes||[]]){let v=attr.value;v=v.replace(/url\(#([^\)]+)\)/g,(_,id)=>`url(#${prefix}-${id})`);if(attr.name==='href'||attr.name==='xlink:href')v=v.replace(/^#/,`#${prefix}-`);if(v!==attr.value)node.setAttribute(attr.name,v)}for(const child of [...node.children||[]])rewrite(child)};
    for(const node of [...doc.documentElement.children]){const clone=node.cloneNode(true);rewrite(clone);if(clone.tagName.toLowerCase()==='defs')root.insertBefore(clone,root.firstChild);else if(clone.id==='graphics')for(const child of [...clone.children])replacement.append(child)}
    use.replaceWith(replacement);
  }
}
function loadNativeQuestions(){if(typeof fetch!=='function')return;document.querySelectorAll('[data-digital-question]').forEach(async host=>{const path=host.dataset.digitalQuestion;try{let pending=nativeMarkupCache.get(path);if(!pending){pending=fetch(path).then(r=>{if(!r.ok)throw Error('Questão indisponível');return r.text()});nativeMarkupCache.set(path,pending)}const markup=await pending;if(host.isConnected&&host.dataset.digitalQuestion===path){host.innerHTML=markup;await inlineNativeFigures(host,path);host.setAttribute('aria-busy','false')}}catch{nativeMarkupCache.delete(path);if(host.isConnected){host.textContent='Não foi possível carregar esta questão. ';const retry=document.createElement('button');retry.className='link';retry.textContent='Tentar novamente';retry.onclick=loadNativeQuestions;host.append(retry);host.setAttribute('aria-busy','false')}}})}
