function themeButton(){const dark=document.documentElement.dataset.theme==='dark';return `<button class="theme-toggle" data-action="theme" aria-label="${dark?'Ativar tema claro':'Ativar tema escuro'}" aria-pressed="${dark}"><span aria-hidden="true">${dark?'☀':'☾'}</span><span>${dark?'Claro':'Escuro'}</span></button>`}
