$('questionOrder').onchange=e=>{questionOrder=e.target.value;const lookup=new Map(QUESTIONS.map(q=>[q.id,q]));currentIds=[...(originalQuestionOrder.length?originalQuestionOrder:currentIds)];if(questionOrder!=='default')currentIds.sort((a,b)=>{const x=lookup.get(a),y=lookup.get(b);if(questionOrder==='topic')return x.topic.localeCompare(y.topic,'pt-BR')||a-b;if(x.year==null)return y.year==null?0:1;if(y.year==null)return -1;return questionOrder==='newest'?y.year-x.year:x.year-y.year});currentIndex=0;render();};
