  const grouped=new Map();
  for(const id of uniqueIds){const topic=questionsById.get(id)?.topic||'Outros assuntos';if(!grouped.has(topic))grouped.set(topic,[]);grouped.get(topic).push(id)}
  const groups=[...grouped].map(([name,groupIds],index)=>({index,name,ids:groupIds,count:groupIds.length}));
  listDrawerReturnFocus=document.activeElement;
  const layer=document.createElement('div');layer.className='list-drawer-layer';
  layer.innerHTML=`<div class="list-drawer-backdrop" data-list-close="true" aria-hidden="true"></div><aside class="list-drawer" role="dialog" aria-modal="true" aria-labelledby="listDrawerTitle"><form id="listDrawerForm" class="list-drawer-form"><header class="list-drawer-header"><div><span class="eyebrow">LISTA DE QUESTÕES</span><h2 id="listDrawerTitle">Criar nova lista</h2></div><button class="icon list-drawer-close" type="button" data-list-close="true" aria-label="Fechar criação da lista">×</button></header><div class="list-drawer-body"><section class="list-drawer-summary" aria-live="polite"><strong>A lista pode ter no máximo ${maxQuestions.toLocaleString('pt-BR')} questões.</strong> <span id="listSelectedMessage"></span><p>Questões repetidas serão incluídas somente uma vez.</p></section><label class="list-name-field"><span>Nome da lista</span><input name="name" required maxlength="100" placeholder="Insira o nome da lista" autocomplete="off"><small><span id="listNameCount">0</span>/100 caracteres</small></label><section class="list-destination"><h3>Salvar nova lista em:</h3><div><span aria-hidden="true">▤</span><strong>Minhas listas</strong></div></section><section class="list-specialties"><div class="list-specialties-title"><div><h3>Número de questões por assunto</h3><p class="muted small">Ajuste a quantidade que deseja estudar em cada assunto.</p></div><button class="link small" id="fitListLimit" type="button" hidden>Ajustar para 1.000</button></div><div id="listSpecialtyRows"></div></section></div><footer class="list-drawer-footer"><p class="modal-error" id="listDrawerError" role="alert"></p><button class="btn full" id="createListSubmit" type="submit"></button></footer></form></aside>`;
  document.body.append(layer);document.body.classList.add('list-drawer-open');
  const rows=layer.querySelector('#listSpecialtyRows'),form=layer.querySelector('#listDrawerForm'),nameInput=form.elements.name;
  const total=()=>groups.reduce((sum,group)=>sum+group.count,0);
  function updateSummary(){
    const selected=total(),over=selected>maxQuestions;
    layer.querySelector('#listSelectedMessage').textContent=`Você selecionou ${selected.toLocaleString('pt-BR')} ${selected===1?'questão':'questões'}.`;
    layer.querySelector('.list-drawer-summary').classList.toggle('over-limit',over);
    layer.querySelector('#fitListLimit').hidden=!over;
    const submit=layer.querySelector('#createListSubmit');
    submit.textContent=`Criar lista com ${selected.toLocaleString('pt-BR')} ${selected===1?'questão':'questões'}`;
    submit.disabled=!nameInput.value.trim()||selected<1||over;
    layer.querySelector('#listDrawerError').textContent=over?`Reduza ${Math.max(0,selected-maxQuestions).toLocaleString('pt-BR')} questões para continuar.`:selected<1?'Escolha pelo menos uma questão.':'';
  }
  function renderRows(){
    rows.innerHTML=groups.filter(group=>group.count>0).map(group=>`<div class="list-specialty-row" data-list-group="${group.index}"><div><strong>${esc(group.name)}</strong><small>${group.ids.length.toLocaleString('pt-BR')} disponíveis</small></div><div class="list-count-controls"><button type="button" data-list-step="-1" aria-label="Diminuir questões de ${esc(group.name)}">−</button><input type="number" inputmode="numeric" min="0" max="${group.ids.length}" value="${group.count}" aria-label="Quantidade de questões de ${esc(group.name)}"><button type="button" data-list-step="1" aria-label="Aumentar questões de ${esc(group.name)}">+</button><button class="list-remove-topic" type="button" data-list-remove="true" aria-label="Remover ${esc(group.name)} da lista"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 11v5M14 11v5"/></svg></button></div></div>`).join('')||'<div class="list-empty-selection">Todos os assuntos foram removidos.</div>';
    updateSummary();
  }
  nameInput.addEventListener('input',()=>{layer.querySelector('#listNameCount').textContent=nameInput.value.length;updateSummary()});
  rows.addEventListener('input',event=>{if(event.target.tagName!=='INPUT')return;const group=groups[Number(event.target.closest('[data-list-group]').dataset.listGroup)],value=Math.round(Number(event.target.value));group.count=Math.max(0,Math.min(group.ids.length,Number.isFinite(value)?value:0));event.target.value=group.count;updateSummary()});
  rows.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const group=groups[Number(button.closest('[data-list-group]').dataset.listGroup)];if(button.dataset.listRemove){group.count=0;renderRows();return}if(button.dataset.listStep){group.count=Math.max(0,Math.min(group.ids.length,group.count+Number(button.dataset.listStep)));if(!group.count)renderRows();else{button.parentElement.querySelector('input').value=group.count;updateSummary()}}});
  layer.querySelector('#fitListLimit').addEventListener('click',()=>{const selected=total();if(selected<=maxQuestions)return;const ratio=maxQuestions/selected;for(const group of groups)group.count=Math.floor(group.count*ratio);let remaining=maxQuestions-total();for(const group of groups){const add=Math.min(remaining,group.ids.length-group.count);group.count+=add;remaining-=add;if(!remaining)break}renderRows()});
  layer.addEventListener('click',event=>{if(event.target.closest('[data-list-close]'))closeListDrawer()});
