function topicBars(attempts){const groups=TOPICS.map(([t])=>{const a=attempts.filter(a=>QUESTIONS.find(q=>q.id===a.id)?.topic===t);return {t,n:a.length,correct:a.filter(x=>x.correct).length}}).filter(x=>x.n);return groups.map(g=>`<div class="barrow"><div class="row"><span>${esc(g.t)}</span><span>${g.correct}/${g.n} · ${Math.round(g.correct/g.n*100)}%</span></div><div class="bartrack"><div class="barfill" style="width:${g.correct/g.n*100}%"></div></div></div>`).join('')}
function renderPerformance(){if(!state.attempts.length){$('main').innerHTML=intro('Seu esforço, em perspectiva.','Acompanhe sua evolução exclusivamente em matemática.')+emptyHTML('Seu histórico começa na primeira questão','Resolva exercícios para descobrir seus pontos fortes e os assuntos que merecem atenção.');return}const total=state.attempts.length,correct=state.attempts.filter(a=>a.correct).length;const dates=[...new Set(state.attempts.map(a=>a.at.slice(0,10)))].slice(-7);const vals=dates.map(d=>state.attempts.filter(a=>a.at.startsWith(d)).length);const max=Math.max(...vals);const errors=TOPICS.map(([t])=>({t,n:state.attempts.filter(a=>!a.correct&&QUESTIONS.find(q=>q.id===a.id)?.topic===t).length})).filter(x=>x.n).sort((a,b)=>b.n-a.n);$('main').innerHTML=intro('Seu esforço, em perspectiva.','Todas as tentativas de matemática são consideradas, inclusive novas tentativas e simulados finalizados.')+`<div class="stats">${stat('Questões respondidas · tentativas',total)}${stat('Percentual de acertos',Math.round(correct/total*100)+'%')}${stat('Acertos',correct)}${stat('Erros',total-correct)}</div><div class="grid2"><section class="card"><h3>Desempenho por assunto</h3>${topicBars(state.attempts)}</section><div class="stack"><section class="card"><h3>Evolução ao longo do tempo</h3><p class="muted small">Tentativas por dia · últimos dias com atividade</p><div class="progress-chart" role="img" aria-label="${dates.map((d,i)=>d+': '+vals[i]+' tentativas').join('; ')}">${dates.map((d,i)=>`<div class="daybar" style="height:${vals[i]/max*100}%"><b>${vals[i]}</b><span>${d.slice(8)}/${d.slice(5,7)}</span></div>`).join('')}</div></section><section class="card"><h3>Onde concentrar sua revisão</h3>${errors.length?errors.slice(0,5).map(x=>`<div class="barrow row"><span>${esc(x.t)}</span><strong>${x.n} erros</strong></div>`).join(''):'<p class="muted small">Nenhum erro registrado até agora.</p>'}</section></div></div><section class="card" style="margin-top:24px"><h3>Histórico de simulados</h3>${state.exams.length?`<div class="table-wrap"><table><thead><tr><th>Simulado</th><th>Data</th><th>Aproveitamento</th><th>Tempo</th><th>Resultado</th></tr></thead><tbody>${state.exams.map(e=>`<tr><td>${esc(e.name)}</td><td>${new Date(e.finishedAt).toLocaleDateString('pt-BR')}</td><td>${scoreExam(e).rate}%</td><td>${timeString(e.used)}</td><td><button class="link" data-exam-result="${e.id}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Você ainda não finalizou um simulado.</p>'}</section>`}
