function showDifficultyMethod(q=null){
  const counts=QUESTIONS.reduce((result,item)=>(result[item.difficulty]=(result[item.difficulty]||0)+1,result),{});
  modal(`<h2>Como classificamos a dificuldade</h2><p>Fácil, Média e Difícil são faixas editoriais de estudo, não uma classificação oficial nem uma taxa real de acertos.</p>${q?`<p><strong>${esc(q.difficulty)} · ${esc(q.difficultyMethod||'Avaliação autoral')}</strong><br>${esc(q.difficultyReason||'Nível definido para o exercício autoral.')}</p>`:''}<p>As questões importadas recebem uma <strong>estimativa pelo perfil da prova</strong>. IME e ITA: difícil; ESA e EEAR: média; CFN: fácil. Outras faixas são provisórias. Uma questão simples pode aparecer em uma prova difícil.</p><p>Quando não há referência específica para a prova, usamos uma <strong>triagem automática pelo assunto</strong>: fundamentos → fácil; cálculo avançado → difícil; demais assuntos → média. Essas questões exigem revisão individual. Não tratamos essa triagem como consenso da internet.</p><p>As questões autorais mantêm a classificação original. Não usamos concorrência, nota de corte ou desempenho fictício como dificuldade.</p><p>${['Fácil','Média','Difícil'].map(level=>`${level}: ${counts[level]||0}`).join(' · ')}</p><h3>Referências e limites</h3><ul>${DIFFICULTY_REFERENCES.map(source=>`<li><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)}</a><p class="small muted">${esc(source.note)}</p></li>`).join('')}</ul><p class="small muted">Critério editorial PRUMO · 20/10/2026. Não substitui a revisão de cada questão.</p>`);
}
const FILTER_META_TABS={};
function metadataValue(q,key){return q[key]??q.metadata?.[key]??''}
function renderMetadataFilter(key){
  const meta=FILTER_META_TABS[key],options=[...new Set(QUESTIONS.map(q=>String(metadataValue(q,key)).trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  $('filterHeading').textContent=options.length?`${options.length} opções encontradas`:meta.label;
  $('filterOptions').innerHTML=options.length?`<div class="filter-list">${options.map(x=>`<label class="checkrow"><input type="checkbox" data-multi="${key}" value="${esc(x)}" ${filters[key].includes(x)?'checked':''}>${esc(x)} <small>(${QUESTIONS.filter(q=>String(metadataValue(q,key)).trim()===x).length})</small></label>`).join('')}</div>`:`<div class="metadata-empty"><strong>${esc(meta.label)}</strong><p>${esc(meta.empty)}</p><span>Quando o acervo receber essa informação, ela aparecerá aqui automaticamente.</span></div>`;
}
function harmonizeFilterTabs(){
  const tabsBar=document.querySelector('.tabs');if(!tabsBar)return;
  const topicTab=tabsBar.querySelector('[data-tab="topics"]');if(topicTab)topicTab.textContent='Matéria / Assunto';
}
function harmonizeFilterSummary(){
  const body=document.querySelector('.filter-grid>.filter-card:nth-child(2) .filter-body');if(!body)return;
  const title=body.querySelector('h3');if(!title)return;title.textContent='Incluir questões';
  let row=body.querySelector('.summary-title-row');
  if(!row){row=document.createElement('div');row.className='summary-title-row';title.parentNode.insertBefore(row,title);row.append(title)}
  if(!row.querySelector('[data-action="edit-advanced"]')){const edit=document.createElement('button');edit.type='button';edit.className='filter-edit-button';edit.dataset.action='edit-advanced';edit.setAttribute('aria-label','Editar filtros avançados');edit.textContent='✎';row.append(edit)}
}
function selectedFilterEntries(){
  const entries=[];
  for(const key of ['topics','institution','year','difficulty'])for(const value of filters[key]||[])entries.push([key,value,value]);
  const labels={'Não resolvidas':'Questões que não estão resolvidas','Já resolvidas':'Questões que já resolvi','Respondidas corretamente':'Questões que acertei','Respondidas incorretamente':'Questões que errei','Texto':'Com solução em texto','Gabarito':'Com gabarito em texto'};
  for(const key of ['type','status','resolution'])for(const value of filterValues(filters[key]))entries.push([key,value,labels[value]||value]);
  if(filters.favorites)entries.push(['favorites','favorites','Somente questões favoritas']);
  return entries;
}
const defaultRenderFilterOptions=renderFilterOptions;
renderFilterOptions=function(){
  document.querySelector('.filter-grid')?.classList.remove('advanced-mode');
  if(tab==='advanced'){
    renderAdvancedFilters();
    document.querySelector('.filter-grid')?.classList.add('advanced-mode');
  }else if(tab==='institution')renderInstitutionFilter();
  else if(FILTER_META_TABS[tab])renderMetadataFilter(tab);
  else defaultRenderFilterOptions();
  cleanFilterSummaryChrome();
};
const defaultUpdateFilterSummary=updateFilterSummary;
updateFilterSummary=function(){
  defaultUpdateFilterSummary();
  const entries=selectedFilterEntries();
  $('chips').innerHTML=entries.length?entries.map(([key,value,label])=>`<span class="chip">${esc(label)}<button data-remove="${key}" data-value="${esc(value)}" aria-label="Remover filtro ${esc(label)}">×</button></span>`).join(''):'<span class="muted small">Nenhum filtro aplicado. Explore todo o acervo.</span>';
  harmonizeFilterSummary();
};
const defaultRenderFilters=renderFilters;
renderFilters=function(){
  defaultRenderFilters();
  harmonizeFilterTabs();
};
const originalQuestionHeader=questionHeader;
questionHeader=function(q){return originalQuestionHeader(q)};
let suppressInlineResolution=false;
const originalSolutionHTML=solutionHTML;
solutionHTML=function(q,selected){return suppressInlineResolution?'':originalSolutionHTML(q,selected)};
const originalRenderQuestion=renderQuestion;
renderQuestion=function(){const previous=suppressInlineResolution;suppressInlineResolution=true;try{const result=originalRenderQuestion();document.querySelectorAll('.question-pages [data-action="retry"],.question-toolbar [data-action="shortcuts"]').forEach(button=>button.remove());window.loadVisibleBankQuestions?.();return result}finally{suppressInlineResolution=previous}};
render();

document.addEventListener('click',e=>{
  const b=e.target.closest('[data-question-favorite],[data-question-list],[data-add-existing],[data-action="history"],[data-advanced-filter]');
  if(!b)return;
  e.stopImmediatePropagation();
  if(b.dataset.advancedFilter){
    if(b.disabled)return;
    const group=b.dataset.advancedFilter,value=b.dataset.advancedValue;
    if(group==='favorites')filters.favorites=!filters.favorites;
    else {const values=filterValues(filters[group]);filters[group]=values.includes(value)?values.filter(x=>x!==value):[...values,value]}
    const active=group==='favorites'?Boolean(filters.favorites):filterValues(filters[group]).includes(value);
    b.classList.toggle('active',active);
    b.setAttribute('aria-checked',String(active));
    updateFilterSummary();return;
  }
  if(b.dataset.questionFavorite){
    const id=Number(b.dataset.questionFavorite);
    state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];
    save();render();return;
  }
  if(b.dataset.questionList){addToList(Number(b.dataset.questionList));return}
  if(b.dataset.addExisting){
    const list=state.lists.find(x=>x.id===b.dataset.addExisting),id=pendingListQuestionId;
    if(list&&id&&!list.ids.includes(id))list.ids.push(id);
    save();$('modal').close();toast('Questão adicionada à lista.');return;
  }
  if(b.dataset.action==='history'){
    const card=b.closest('[data-question-id]'),id=activeQuestionId(card),attempts=state.attempts.filter(x=>x.id===id);
    modal(`<h2>Histórico de respostas</h2><p class="muted small">${attempts.length?`${attempts.length} tentativa${attempts.length===1?'':'s'} registrada${attempts.length===1?'':'s'} neste navegador.`:'Ainda não há tentativas registradas para esta questão.'}</p>${attempts.length?`<div class="stack">${attempts.slice().reverse().map(a=>`<div class="notice">${a.correct?'✓ Acerto':'✕ Erro'} · ${new Date(a.at).toLocaleString('pt-BR')}</div>`).join('')}</div>`:'<p class="notice">Responda à questão para começar seu histórico.</p>'}`);return;
  }
},true);
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action="edit-advanced"]');
  if(!b)return;
  e.stopImmediatePropagation();
  tab='advanced';
  renderFilters();
},true);
document.addEventListener('keydown',e=>{if(page!=='resolve'||$('modal').open||!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const action=e.key==='ArrowRight'?'toolbar-next':'toolbar-prev';document.querySelector('[data-action="'+action+'"]:not(:disabled)')?.click()});
const newQuestionsScript=document.createElement('script');newQuestionsScript.src='novas-questoes.js';document.head.appendChild(newQuestionsScript);
